UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Active Recreation and Consumer Health', m.description = 'Staying active through recreation, and making wise choices about health products and services.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Plan safe active recreational activities</li><li>Explain the benefits of active recreation</li><li>Evaluate health products and services as a smart consumer</li></ul></blockquote><h3>Part 1: Physical Education – Active Recreation</h3><p><strong>Active recreation</strong> is any physical activity done during free time for enjoyment, such as hiking, biking, swimming, dancing, or playing sports with friends.</p><h4>Benefits</h4><ul><li><strong>Physical:</strong> improves heart health, strength, and flexibility.</li><li><strong>Mental:</strong> reduces stress and improves mood.</li><li><strong>Social:</strong> builds friendships and teamwork.</li></ul><h4>Planning a safe activity</h4><ol><li>Choose an activity that fits your fitness level.</li><li>Check the weather and the place beforehand.</li><li>Bring water, proper clothing, and a first aid kit.</li><li>Warm up before and cool down after.</li><li>Never go alone; tell someone where you are going.</li><li>Follow "Leave No Trace": bring your trash home.</li></ol><blockquote><p><strong>Example</strong></p><p>For a morning hike, a group starts at 6 a.m. to avoid the midday heat, brings two liters of water each, wears closed shoes, and informs the barangay or park office of their route.</p></blockquote><h3>Part 2: Health – Consumer Health</h3><p><strong>Consumer health</strong> is about choosing health products, services, and information wisely. A smart consumer protects both their health and their money.</p><h4>Reading a product label</h4><table><thead><tr><th>Check</th><th>Why it matters</th></tr></thead><tbody><tr><td>Expiration date</td><td>Expired products may be unsafe</td></tr><tr><td>Ingredients</td><td>Avoid allergens and harmful substances</td></tr><tr><td>Directions and dosage</td><td>Using too much can be dangerous</td></tr><tr><td>FDA registration</td><td>Shows the product passed safety standards in the Philippines</td></tr></tbody></table><h4>Spotting false claims</h4><ul><li>Promises like "cures all diseases" or "lose 10 kg in a week"</li><li>Testimonials only, with no scientific evidence</li><li>Pressure to "buy now" before a deadline</li></ul><blockquote><p><strong>Remember</strong></p><p>Food supplements are not medicine. Products labeled "No approved therapeutic claims" cannot claim to cure or treat illness.</p></blockquote><h3>Activity</h3><p>Part A: Plan a one-day active recreation outing for your family, listing the activity, schedule, things to bring, and safety rules. Part B: Examine one health product at home and record its expiration date, main ingredients, dosage, and whether it has an FDA registration number.</p><h3>Quick check</h3><ol><li>Give one mental benefit of active recreation.</li><li>Why should you check the FDA registration of a product?</li><li>Give one sign of a false health claim.</li></ol><details><summary>Show answers</summary><ol><li>Any one: reduces stress, improves mood.</li><li>It shows the product passed safety standards.</li><li>Any one: promises a cure for everything, unrealistic results, testimonials only, pressure to buy now.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-MAPEH' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Active Recreation and Consumer Health', 'Staying active through recreation, and making wise choices about health products and services.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Plan safe active recreational activities</li><li>Explain the benefits of active recreation</li><li>Evaluate health products and services as a smart consumer</li></ul></blockquote><h3>Part 1: Physical Education – Active Recreation</h3><p><strong>Active recreation</strong> is any physical activity done during free time for enjoyment, such as hiking, biking, swimming, dancing, or playing sports with friends.</p><h4>Benefits</h4><ul><li><strong>Physical:</strong> improves heart health, strength, and flexibility.</li><li><strong>Mental:</strong> reduces stress and improves mood.</li><li><strong>Social:</strong> builds friendships and teamwork.</li></ul><h4>Planning a safe activity</h4><ol><li>Choose an activity that fits your fitness level.</li><li>Check the weather and the place beforehand.</li><li>Bring water, proper clothing, and a first aid kit.</li><li>Warm up before and cool down after.</li><li>Never go alone; tell someone where you are going.</li><li>Follow "Leave No Trace": bring your trash home.</li></ol><blockquote><p><strong>Example</strong></p><p>For a morning hike, a group starts at 6 a.m. to avoid the midday heat, brings two liters of water each, wears closed shoes, and informs the barangay or park office of their route.</p></blockquote><h3>Part 2: Health – Consumer Health</h3><p><strong>Consumer health</strong> is about choosing health products, services, and information wisely. A smart consumer protects both their health and their money.</p><h4>Reading a product label</h4><table><thead><tr><th>Check</th><th>Why it matters</th></tr></thead><tbody><tr><td>Expiration date</td><td>Expired products may be unsafe</td></tr><tr><td>Ingredients</td><td>Avoid allergens and harmful substances</td></tr><tr><td>Directions and dosage</td><td>Using too much can be dangerous</td></tr><tr><td>FDA registration</td><td>Shows the product passed safety standards in the Philippines</td></tr></tbody></table><h4>Spotting false claims</h4><ul><li>Promises like "cures all diseases" or "lose 10 kg in a week"</li><li>Testimonials only, with no scientific evidence</li><li>Pressure to "buy now" before a deadline</li></ul><blockquote><p><strong>Remember</strong></p><p>Food supplements are not medicine. Products labeled "No approved therapeutic claims" cannot claim to cure or treat illness.</p></blockquote><h3>Activity</h3><p>Part A: Plan a one-day active recreation outing for your family, listing the activity, schedule, things to bring, and safety rules. Part B: Examine one health product at home and record its expiration date, main ingredients, dosage, and whether it has an FDA registration number.</p><h3>Quick check</h3><ol><li>Give one mental benefit of active recreation.</li><li>Why should you check the FDA registration of a product?</li><li>Give one sign of a false health claim.</li></ol><details><summary>Show answers</summary><ol><li>Any one: reduces stress, improves mood.</li><li>It shows the product passed safety standards.</li><li>Any one: promises a cure for everything, unrealistic results, testimonials only, pressure to buy now.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-MAPEH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

-- HS10-TLE
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Planning a Small Business', m.description = 'Turning a product idea into a simple, workable business plan.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Identify a business opportunity in your community</li><li>Compute the cost and selling price of a product</li><li>Prepare a simple business plan</li></ul></blockquote><p>Many big businesses started small: a home kitchen, a single sewing machine, or a repair table in a garage. The difference between an idea and a business is a <strong>plan</strong>.</p><h3>Finding an opportunity</h3><p>A good business answers a <strong>need</strong> or <strong>want</strong> in the community.</p><ul><li>What do people in your area often look for but cannot easily buy?</li><li>What skill from your TLE specialization can you turn into a product or service?</li><li>Who would buy it, and how often?</li></ul><blockquote><p><strong>Example</strong></p><p>A student taking Cookery notices that office workers near the school have few healthy snack options. She plans to sell vegetable lumpia packs during lunch breaks.</p></blockquote><h3>Computing cost and price</h3><p><strong>Total cost</strong> = materials + labor + overhead (electricity, gas, packaging)<br><strong>Cost per unit</strong> = total cost ÷ number of units<br><strong>Selling price</strong> = cost per unit + markup</p><table><thead><tr><th>Item (for 20 packs)</th><th>Cost</th></tr></thead><tbody><tr><td>Ingredients</td><td>₱400</td></tr><tr><td>Packaging</td><td>₱60</td></tr><tr><td>Gas and utilities</td><td>₱40</td></tr><tr><td><strong>Total cost</strong></td><td><strong>₱500</strong></td></tr></tbody></table><p>Cost per pack = ₱500 ÷ 20 = ₱25. With a 40% markup: ₱25 + (0.40 × ₱25) = <strong>₱35 per pack</strong>.<br>Profit for 20 packs = (₱35 × 20) − ₱500 = <strong>₱200</strong>.</p><h3>Parts of a simple business plan</h3><ol><li><strong>Business name and description</strong> – what you sell and why.</li><li><strong>Target market</strong> – who will buy.</li><li><strong>Competitors</strong> – who else sells something similar, and how you are different.</li><li><strong>Costing and pricing</strong> – your computations.</li><li><strong>Operations</strong> – where, when, and how you will produce and sell.</li><li><strong>Goals</strong> – what you want to achieve in the first month.</li></ol><h3>Activity</h3><p>Write a one-page business plan for a product or service related to your TLE specialization. Include all six parts and a costing table with the selling price per unit.</p><h3>Quick check</h3><ol><li>What three costs make up total cost?</li><li>If total cost is ₱600 for 30 units, what is the cost per unit?</li><li>Why should a business plan include competitors?</li></ol><details><summary>Show answers</summary><ol><li>Materials, labor, and overhead</li><li>₱20</li><li>To know how your product is different and price it competitively.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-TLE' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Planning a Small Business', 'Turning a product idea into a simple, workable business plan.', '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Identify a business opportunity in your community</li><li>Compute the cost and selling price of a product</li><li>Prepare a simple business plan</li></ul></blockquote><p>Many big businesses started small: a home kitchen, a single sewing machine, or a repair table in a garage. The difference between an idea and a business is a <strong>plan</strong>.</p><h3>Finding an opportunity</h3><p>A good business answers a <strong>need</strong> or <strong>want</strong> in the community.</p><ul><li>What do people in your area often look for but cannot easily buy?</li><li>What skill from your TLE specialization can you turn into a product or service?</li><li>Who would buy it, and how often?</li></ul><blockquote><p><strong>Example</strong></p><p>A student taking Cookery notices that office workers near the school have few healthy snack options. She plans to sell vegetable lumpia packs during lunch breaks.</p></blockquote><h3>Computing cost and price</h3><p><strong>Total cost</strong> = materials + labor + overhead (electricity, gas, packaging)<br><strong>Cost per unit</strong> = total cost ÷ number of units<br><strong>Selling price</strong> = cost per unit + markup</p><table><thead><tr><th>Item (for 20 packs)</th><th>Cost</th></tr></thead><tbody><tr><td>Ingredients</td><td>₱400</td></tr><tr><td>Packaging</td><td>₱60</td></tr><tr><td>Gas and utilities</td><td>₱40</td></tr><tr><td><strong>Total cost</strong></td><td><strong>₱500</strong></td></tr></tbody></table><p>Cost per pack = ₱500 ÷ 20 = ₱25. With a 40% markup: ₱25 + (0.40 × ₱25) = <strong>₱35 per pack</strong>.<br>Profit for 20 packs = (₱35 × 20) − ₱500 = <strong>₱200</strong>.</p><h3>Parts of a simple business plan</h3><ol><li><strong>Business name and description</strong> – what you sell and why.</li><li><strong>Target market</strong> – who will buy.</li><li><strong>Competitors</strong> – who else sells something similar, and how you are different.</li><li><strong>Costing and pricing</strong> – your computations.</li><li><strong>Operations</strong> – where, when, and how you will produce and sell.</li><li><strong>Goals</strong> – what you want to achieve in the first month.</li></ol><h3>Activity</h3><p>Write a one-page business plan for a product or service related to your TLE specialization. Include all six parts and a costing table with the selling price per unit.</p><h3>Quick check</h3><ol><li>What three costs make up total cost?</li><li>If total cost is ₱600 for 30 units, what is the cost per unit?</li><li>Why should a business plan include competitors?</li></ol><details><summary>Show answers</summary><ol><li>Materials, labor, and overhead</li><li>₱20</li><li>To know how your product is different and price it competitively.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS10-TLE' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Marketing Your Product', m.description = 'Using the 4Ps and simple promotion to reach customers.', m.content = '<blockquote><p><strong>By the end of this module, you should be able to:</strong></p><ul><li>Apply the 4Ps of marketing to a product</li><li>Identify a target market</li><li>Create a simple promotion for a small business</li></ul></blockquote><p>A great product will not sell if nobody knows about it. <strong>Marketing</strong> connects your product to the people who need it.</p><h3>The 4Ps of marketing</h3><table><thead><tr><th>P</th><th>Question it answers</th><th>Example (vegetable lumpia packs)</th></tr></thead><tbody><tr><td>Product</td><td>What are you selling, and what makes it special?</td><td>Fresh, healthy lumpia with vinegar dip</td></tr><tr><td>Price</td><td>How much will customers pay?</td><td>₱35 per pack, ₱100 for 3</td></tr><tr><td>Place</td><td>Where will customers buy it?</td><td>Near the office building gate, 11 a.m. to 1 p.m.</td></tr><tr><td>Promotion</td><td>How will people find out about it?</td><td>Flyers, Facebook page, free taste on opening day</td></tr></tbody></table><h3>Knowing your target market</h3><p>Your <strong>target market</strong> is the specific group most likely to buy. Describe them by:</p><ul><li><strong>Age and occupation</strong> – e.g., office workers aged 25–45</li><li><strong>Location</strong> – e.g., working near the school area</li><li><strong>Needs</strong> – e.g., quick, affordable, healthy lunch</li></ul><h3>Low-cost promotion ideas</h3><ul><li>A Facebook or Instagram page with clear photos and prices</li><li>Simple flyers with your product, price, and contact number</li><li>Bundle deals and loyalty cards (buy 5, get 1 free)</li><li>Asking satisfied customers to recommend you</li></ul><blockquote><p><strong>Example of a good social media post</strong></p><p>"Healthy na, busog pa! 🥬 Fresh vegetable lumpia, ₱35 per pack or 3 for ₱100. Available Mon–Fri, 11 AM–1 PM at the school gate. Message us to reserve!"<br>It states the benefit, product, price, place, time, and how to order.</p></blockquote><h3>Packaging matters</h3><ul><li>Keeps the product clean and safe</li><li>Shows your brand name and contact details</li><li>Makes the product attractive and easy to carry</li></ul><h3>Activity</h3><p>Using the product from your business plan, fill in a 4Ps table, describe your target market in three sentences, and write one social media post that includes the benefit, price, place, time, and how to order.</p><h3>Quick check</h3><ol><li>What are the 4Ps of marketing?</li><li>What is a target market?</li><li>Give two low-cost ways to promote a small business.</li></ol><details><summary>Show answers</summary><ol><li>Product, Price, Place, Promotion</li><li>The specific group of people most likely to buy the product.</li><li>Any two: social media page, flyers, bundle deals, loyalty cards, word of mouth.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS10-TLE' AND m.module_number = 2 AND m.updated_by IS NULL;
